import{z as s,x as l,o as A,c as d,q as r,j as n,D as B,d as E,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"事务管理器的实现","description":"","frontmatter":{"title":"事务管理器的实现","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dbk-tx-manager.md","filePath":"cs/dbk-tx-manager.md","lastUpdated":1791413859000}'),C={name:"cs/dbk-tx-manager.md"};function p(c,a,m,h,D,F){const t=l("Mermaid");return A(),d("div",null,[a[2]||(a[2]=r('<h1 id="事务管理器的实现" tabindex="-1">事务管理器的实现 <a class="header-anchor" href="#事务管理器的实现" aria-label="Permalink to &quot;事务管理器的实现&quot;">​</a></h1><div class="epigraph"><p>执行器只管改页；什么时候这些改动算数、哪两个改动不能同时发生，是事务管理器的账本。</p><footer>—— 据 Bernstein, Hadzilacos and Goodman, *Concurrency Control and Recovery in Database Systems*, 1987；Gray and Reuter, *Transaction Processing*, 1993 整理</footer></div><p><a href="/cs/dbk-executor-implementation">上一课</a>把扫描算子的最后一道工序留了白：每吐一行先问「对我的快照可见吗」，每个改动先问「与谁冲突」。回答这两问的组件就是本课的事务管理器。主干已把<a href="/cs/conflict-serializable">冲突可串行</a>、<a href="/cs/two-pl">两阶段锁</a>、<a href="/cs/mvcc">MVCC</a>与<a href="/cs/snapshot-isolation">快照隔离</a>的语义讲清；本课写组件实现：事务对象与提交序、锁管理器的数据结构与死锁检测、可见性函数怎么查。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实现层的事务管理器是两张账：一张按事务记（谁持有什么锁、写了什么、快照在哪），一张按资源记（哪把锁被谁持有、谁在等）。缺口在于两账必须实时一致：事务回滚了，它排队的锁申请必须同时出队，否则等待者等到的是一把死人的锁；事务提交了，它的写必须对后到的快照可见、对先前的快照不可见。再有三处细节陷阱：升级锁（读转写）不插队，同一事务排在自己后面——最简单的活锁；可见性判断用了「申请序」而不是「提交序」，读到从未提交过的数据；等待不建图，环在系统里无声地转。</p><p><span class="marginnote">两张账可以想成酒店前台与房务板：事务账是客人名单（谁持哪些房卡、住了哪间），资源账是每扇门的挂牌（这间谁住、谁在门外等）。回滚就像客人退房——必须同时撕掉门外等着的牌子，否则等的人对着空房傻等。</span></p><h3 id="锁管理器的账" tabindex="-1">锁管理器的账 <a class="header-anchor" href="#锁管理器的账" aria-label="Permalink to &quot;锁管理器的账&quot;">​</a></h3><p>资源表是一张哈希：资源 id 到锁头；锁头挂两个队列，已授权集合与等待队列。申请者先查兼容性：与授权集合相容则立即入集（读读相容），不相容则入等待队列。升级申请是唯一的插队规则——S 转 X 排到本资源等待队列最前，但仍须等已有的 S 全部释放。释放时从队头唤醒所有与当前授权集合相容的等待者，一并唤醒，避免逐个放行的饥饿。死锁检测在这张表上跑：等待者指向阻塞它的授权者，构成 <a href="/cs/wait-for-graph">wait-for 图</a>，周期性 DFS 找环，找到就按回滚代价选牺牲者；<a href="/cs/wait-die">wait-die 与 wound-wait</a> 的超时法是它的便宜替代——InnoDB 两者都有开关。</p><p><span class="marginnote">InnoDB 默认每次锁等待都即时跑 wait-for 图检测，检测本身在高并发热点行上就是 CPU 大户——所以才有「关掉即时检测、只留 50 秒超时」的生产开关。检测频率是延迟与 CPU 的旋钮，不是对错开关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MVCC 一侧的账更薄。事务 begin 时领一个读视图：当时已分配的最大事务号加活跃事务集合；可见性函数只做集合判断：创建者已提交且在读视图之前、删除者不存在或不可见，版本即可见。扫描算子（上一课）每行调它一次，热点路径上实现成一次位查（提交位图）加集合成员判断。写冲突按「先写者赢」：第一个改某行的事务把行上的写事务号记成自己；快照隔离下第二个并发写者到提交时才检测：核对写集是否被并发改过，有则回滚（first-committer-wins）。提交序是两本账的汇合点：事务管理器从单调序号源领提交序，再把兑现交给 WAL（下一课）。可见性按提交序、持久性按日志序，两个序必须同源，否则「已提交」与「恢复后可见」对不上。</p><p><span class="marginnote">读视图用数字看：begin 时最大已分配事务号是 100，活跃集合是 {97, 99}。某行版本的创建者是 95——已提交且在界内，可见；是 99——还在活跃集合，不可见；是 101——在我 begin 之后才出生，更不可见。可见性就是这三次判断。</span></p>',12)),(A(),n(o,null,{default:B(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEGIN%5B%22begin%EF%BC%9A%E9%A2%86%E8%AF%BB%E8%A7%86%E5%9B%BE%22%5D%20--%3E%20ACTIVE%5B%22%E6%89%A7%E8%A1%8C%EF%BC%9A%E6%89%AB%E6%8F%8F%E8%BF%87%E5%8F%AF%E8%A7%81%E6%80%A7%E5%87%BD%E6%95%B0%22%5D%0A%20%20ACTIVE%20--%3E%20WRITE%7B%22%E9%A6%96%E6%AC%A1%E6%94%B9%E6%9F%90%E8%A1%8C%EF%BC%9F%22%7D%0A%20%20WRITE%20--%3E%7C%E6%98%AF%7C%20LOCK%5B%22%E9%94%81%E7%AE%A1%E7%90%86%E5%99%A8%E7%94%B3%E8%AF%B7%E5%86%99%E9%94%81%22%5D%0A%20%20LOCK%20--%3E%20WAIT%7B%22%E7%9B%B8%E5%AE%B9%EF%BC%9F%22%7D%0A%20%20WAIT%20--%3E%7C%E6%98%AF%7C%20GRANT%5B%22%E5%85%A5%E6%8E%88%E6%9D%83%E9%9B%86%EF%BC%8C%E8%A1%8C%E4%B8%8A%E8%AE%B0%E5%86%99%E8%80%85%22%5D%0A%20%20WAIT%20--%3E%7C%E5%90%A6%7C%20QUEUE%5B%22%E5%85%A5%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%EF%BC%8C%E8%BF%9B%20wait-for%20%E5%9B%BE%22%5D%0A%20%20QUEUE%20--%3E%20DL%7B%22%E6%A3%80%E5%87%BA%E7%8E%AF%EF%BC%9F%22%7D%0A%20%20DL%20--%3E%7C%E6%98%AF%7C%20VICTIM%5B%22%E9%80%89%E7%89%BA%E7%89%B2%E8%80%85%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20DL%20--%3E%7C%E5%90%A6%7C%20GRANT%0A%20%20GRANT%20--%3E%20COMMIT%5B%22%E9%A2%86%E6%8F%90%E4%BA%A4%E5%BA%8F%EF%BC%8C%E4%BA%A4%20WAL%20%E5%85%91%E7%8E%B0%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("两阶段锁与 MVCC 在实现里不是二选一，而是分工：写写冲突由锁管理器在改动发生时挡下（阻塞或死锁回滚），读写冲突由快照吸收（读者不阻塞写者，见的是旧版本）。代价写在锁的粒度上：行锁的资源表在高并发下本身就是热点，于是有"),e("a",{href:"/cs/intention-locks"},"意向锁"),E("把表级判断便宜化。死锁之所以在锁层必须检测、在闩层（第 2 课）不需要，正是任意序与全序的差别：锁的等待关系由业务数据决定，没有可预先固定的获取顺序，图上就可能成环；闩的获取被协议钉成全序，环构造不出来。保存点只是账本上的栈：savepoint 记下锁与写集的标记，回滚到点即弹出其后的条目——主干讲过语义，实现是一次栈操作。")],-1)),a[5]||(a[5]=e("p",null,"两类冲突各自由谁吸收：",-1)),(A(),n(o,null,{default:B(()=>[i(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E4%B8%A4%E4%B8%AA%E4%BA%8B%E5%8A%A1%E5%90%8C%E6%97%B6%E7%A2%B0%E4%B8%80%E8%A1%8C%22%5D%20--%3E%20WW%5B%22%E5%86%99%E5%AF%B9%E5%86%99%22%5D%0A%20%20WW%20--%3E%20LK%5B%22%E9%94%81%E7%AE%A1%E7%90%86%E5%99%A8%E5%BD%93%E5%9C%BA%E6%8C%A1%E4%B8%8B%EF%BC%9A%E9%98%BB%E5%A1%9E%E6%88%96%E6%AD%BB%E9%94%81%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20LK%20--%3E%20S1%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E7%AD%89%E5%BE%85%E4%B8%8E%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20C%20--%3E%20RW%5B%22%E8%AF%BB%E5%AF%B9%E5%86%99%22%5D%0A%20%20RW%20--%3E%20SN%5B%22%E5%BF%AB%E7%85%A7%E5%90%B8%E6%94%B6%EF%BC%9A%E8%AF%BB%E8%80%85%E4%B8%8D%E9%98%BB%E5%A1%9E%EF%BC%8C%E7%9C%8B%E6%97%A7%E7%89%88%E6%9C%AC%22%5D%0A%20%20SN%20--%3E%20S2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E6%97%A7%E7%89%88%E6%9C%AC%E8%A6%81%E7%95%99%E7%9D%80%22%5D%0A"})]),fallback:B(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">初学者容易以为有了 MVCC 就不需要锁了。实际快照只吸收「读对写」：两个事务同时改同一行仍是写写冲突，照样阻塞或回滚。MVCC 的承诺是读者与写者互不拖累，不是写者与写者相安无事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲隔离级别语义（主干快照隔离与异常课已给），不写多粒度锁的完整矩阵（意向锁课已有）；跨库的两阶段提交是分布式事务的事，不在单库组件之内。时间戳排序与 OCC 把冲突判定从改动时点挪到验证时点，组件边界与本课相同，账本结构不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两张账实时一致：事务表（锁、写集、快照）与资源表（授权集、等待队列）。</li><li>升级插队与批量唤醒是锁管理器的两条活命规则，否则自等与饥饿。</li><li>可见性是提交序上的集合判断；提交序与日志序必须同源。</li><li>锁管写写、快照吸收读写；死锁在锁层要检测，在闩层靠全序免疫。</li><li>出处：Bernstein, Hadzilacos and Goodman, 1987；Gray and Reuter, 1993；Mohan et al., ARIES, TODS 1992。</li></ul>',5))])}const T=s(C,[["render",p]]);export{u as __pageData,T as default};
